contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, address recipient) public payable {
        require(caller != address(0));
        require(recipient != address(0));

        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(caller != beforeOwner);

        uint256 beforeBalance = address(c).balance;

        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;

        require(c.owner() == beforeOwner);

        assert(address(c).balance == 0);
    }

    receive() external payable {}
}

